import fs from 'fs';
import path from 'path';

const dirs = [
  'public/images',
  'public/images/hero',
  'public/images/about',
  'public/images/services',
  'public/images/gallery'
];

dirs.forEach(d => {
  if (!fs.existsSync(d)) {
    fs.mkdirSync(d, { recursive: true });
  }
});

// A valid 1x1 or small warm brown PNG or sample PNG:
// Base64 of a clean circular warm logo badge
// We can write a clean 100x100 PNG
const base64Png = '';

fs.writeFileSync('public/images/logo.png', Buffer.from(base64Png, 'base64'));
console.log('Images directories and fallback logo.png created.');
